<script setup lang="ts">import{useRenameStore}from'../../stores/rename';defineProps<{modelValue:boolean}>();defineEmits(['update:modelValue','confirm']);const s=useRenameStore()</script><template><el-dialog :model-value="modelValue" title="确认文件名处理" width="520" :close-on-click-modal="false" @close="$emit('update:modelValue',false)"><el-alert title="执行前请再次核对目标名称" type="warning" :closable="false"/><dl><dt>根目录</dt><dd>{{s.root}}</dd><dt>将执行</dt><dd><b>{{s.summary.ready}}</b> 项</dd><dt>不执行</dt><dd>{{s.summary.unchanged+s.summary.conflicts+s.summary.invalid}} 项（无变化、冲突或阻止）</dd></dl><template #footer><el-button @click="$emit('update:modelValue',false)">返回检查</el-button><el-button type="primary" :disabled="!s.canExecute" @click="$emit('confirm')">确认执行</el-button></template></el-dialog></template><style scoped>dl{display:grid;grid-template-columns:70px 1fr;gap:14px;margin-top:20px}dt{color:var(--muted)}dd{margin:0;word-break:break-all}b{color:var(--primary);font-size:20px}</style>
